	uint32_t status = 0;

	for (int group = 0; group < SOC_TIMER_GROUP_NUM; group++) {
		status |= hw->group[group].ctrl.timer0_en << (bit_pos++);
		status |= hw->group[group].ctrl.timer1_en << (bit_pos++);
		status |= hw->group[group].ctrl.timer2_en << (bit_pos++);
