        return 0;
    }
    timer_ll_set_read_index(hal->hw, chan);
    timer_ll_set_cnt_read(hal->hw, chan);

    //Wait hardware to prepare the data
    BK_WHILE (!timer_ll_is_cnt_read_valid(hal->hw, chan));

    return timer_ll_get_timer_count(hal->hw, chan);
}

