/*
 * chips/bk7258/wifi/glue/hw_driver_shim.c
 *
 * NuttX implementation of the Armino sys_ctrl / sys_ll / gpio / ckmn / aon-rtc
 * callbacks the vendored glue registers into the Wi-Fi driver capability
 * table. Interrupt-enable and modem-clock callbacks map onto the team chip
 * layer register bits (bk7258_memorymap.h); power/OFDM/RC32k/GPIO remain
 * skeleton no-ops until the corresponding team drivers exist.
 */

#include <nuttx/config.h>
#include <nuttx/arch.h>

/* getreg32 is an ARM internal macro, not a linkable function. This shim is
 * self-developed and therefore does not receive bk_prelude.h (which is scoped
 * to vendored sources); include the real NuttX definition here explicitly.
 */

#include <arm_internal.h>

#include <stdint.h>
#include <stdbool.h>

#include <bk7258_memorymap.h>

#include "sys_driver.h"
#include "sys_ll.h"
#include "gpio_driver.h"
#include "driver/ckmn.h"
#include "driver/aon_rtc.h"
#include "driver/int.h"
#include "driver/adc.h"
#include "driver/gpio.h"
#include "aon_pmu_hal.h"
#include "aon_pmu_driver.h"

/****************************************************************************
 * Interrupt enable (SYS_CPU0_INT_EN / INT_EN_HI)
 ****************************************************************************/

int32_t sys_drv_int_enable(uint32_t param)
{
  modifyreg32(BK7258_SYS_CPU0_INT_EN, param, param);
  return 0;
}

int32_t sys_drv_int_disable(uint32_t param)
{
  modifyreg32(BK7258_SYS_CPU0_INT_EN, param, 0);
  return 0;
}

int32_t sys_drv_int_group2_enable(uint32_t param)
{
  modifyreg32(BK7258_SYS_CPU0_INT_EN_HI, param, param);
  return 0;
}

int32_t sys_drv_int_group2_disable(uint32_t param)
{
  modifyreg32(BK7258_SYS_CPU0_INT_EN_HI, param, 0);
  return 0;
}

uint32_t sys_drv_enable_mac_gen_int(void)
{
  modifyreg32(BK7258_SYS_CPU0_INT_EN_HI,
              BK7258_SYS_WIFI_MAC_GEN_INT_EN,
              BK7258_SYS_WIFI_MAC_GEN_INT_EN);
  return 0;
}

uint32_t sys_drv_enable_mac_prot_int(void)
{
  modifyreg32(BK7258_SYS_CPU0_INT_EN_HI,
              BK7258_SYS_WIFI_MAC_PROT_TRIGGER_INT_EN,
              BK7258_SYS_WIFI_MAC_PROT_TRIGGER_INT_EN);
  return 0;
}

uint32_t sys_drv_enable_mac_tx_trigger_int(void)
{
  modifyreg32(BK7258_SYS_CPU0_INT_EN_HI,
              BK7258_SYS_WIFI_MAC_TX_TRIGGER_INT_EN,
              BK7258_SYS_WIFI_MAC_TX_TRIGGER_INT_EN);
  return 0;
}

uint32_t sys_drv_enable_mac_rx_trigger_int(void)
{
  modifyreg32(BK7258_SYS_CPU0_INT_EN_HI,
              BK7258_SYS_WIFI_MAC_RX_TRIGGER_INT_EN,
              BK7258_SYS_WIFI_MAC_RX_TRIGGER_INT_EN);
  return 0;
}

uint32_t sys_drv_enable_mac_txrx_misc_int(void)
{
  modifyreg32(BK7258_SYS_CPU0_INT_EN_HI,
              BK7258_SYS_WIFI_MAC_TXRX_MISC_INT_EN,
              BK7258_SYS_WIFI_MAC_TXRX_MISC_INT_EN);
  return 0;
}

uint32_t sys_drv_enable_mac_txrx_timer_int(void)
{
  modifyreg32(BK7258_SYS_CPU0_INT_EN,
