UINT32 get_net_info(NET_INFO_ITEM item, UINT8 *ptr0, UINT8 *ptr1, UINT8 *ptr2)
{
  (void)ptr1;
  (void)ptr2;

  /* Clear rather than leave untouched: see the safety note above. */

  switch (item)
    {
      case WIFI_MAC_ITEM:
        if (ptr0 != NULL)
          {
            memset(ptr0, 0, 6);
          }
        break;

      case FAST_CONNECT_ITEM:
        if (ptr0 != NULL)
          {
            memset(ptr0, 0, sizeof(struct wlan_fast_connect_info));
          }
        break;

      default:
        break;
    }

  /* Non-zero: no persistent network parameter store on BK7258 yet. */

  return (UINT32)BK_FAIL;
}

