/*
 * chips/bk7258/wifi/glue/net_param_shim.c
 *
 * Replaces the vendored net_param.c, which stores the MAC address and the
 * fast-connect record in a flash partition (BK_PARTITION_SYS_NET) through the
 * Armino flash/driver-model stack (bk_flash_partition_read, ddev_open, ...).
 * None of that is ported for BK7258 yet, so keeping the original file would
 * mean stubbing six flash APIs plus four Armino driver headers.
 *
 * Safety note: upstream returns 0 on both success and failure here
 * (`ret` starts at 0 and success assigns BK_OK, which is also 0), so a caller
 * cannot tell them apart from the return code. libwifi.a calls these through
 * g_wifi_funcs, and acting on an unfilled fast-connect record would make the
 * runtime try to associate with garbage. Therefore we always clear the caller's
 * buffer before returning -- that, not the return value, is what keeps the
 * behaviour safe.
 */

#include <nuttx/config.h>

#include <stdint.h>
#include <string.h>

#include <common/bk_include.h>
#include <common/bk_err.h>

#include "bk_wifi.h"

/****************************************************************************
 * Public functions
 ****************************************************************************/

UINT32 get_net_info(NET_INFO_ITEM item, UINT8 *ptr0, UINT8 *ptr1, UINT8 *ptr2)
{
  (void)ptr1;
  (void)ptr2;

  /* Clear rather than leave untouched: see the safety note above. */

  switch (item)
    {
      case WIFI_MAC_ITEM:
        if (ptr0 != NULL)
          {
            memset(ptr0, 0, 6);
          }
        break;

      case FAST_CONNECT_ITEM:
        if (ptr0 != NULL)
          {
            memset(ptr0, 0, sizeof(struct wlan_fast_connect_info));
          }
        break;

      default:
        break;
    }

  /* Non-zero: no persistent network parameter store on BK7258 yet. */

  return (UINT32)BK_FAIL;
}

UINT32 save_net_info(NET_INFO_ITEM item, UINT8 *ptr0, UINT8 *ptr1, UINT8 *ptr2)
{
  (void)item;
  (void)ptr0;
  (void)ptr1;
  (void)ptr2;

  return (UINT32)BK_FAIL;
}

/* These two are compatibility placeholders upstream too: net_param.c:132-140
 * returns 0 without reading or writing any pointer. Reproduce that exact
 * behaviour rather than inventing persistence semantics.
 */

UINT32 get_info_item(NET_INFO_ITEM item, UINT8 *ptr0, UINT8 *ptr1, UINT8 *ptr2)
{
  (void)item;
  (void)ptr0;
  (void)ptr1;
  (void)ptr2;
  return 0;
}

UINT32 save_info_item(NET_INFO_ITEM item, UINT8 *ptr0, UINT8 *ptr1,
                      UINT8 *ptr2)
{
  (void)item;
  (void)ptr0;
  (void)ptr1;
  (void)ptr2;
 * out-of-spec RF output.
 *
 * Temperature/voltage monitoring lives in glue/analog_shim.c, not here.
 *
 * Before RF bring-up (plan step 4) this file must be implemented for real: add
 * the RF partition to the team flash layout, then read it via the NuttX
 * MTD/progmem interface. Tracked in ABI_AUDIT.md alongside the analog items.
 */

#include <nuttx/config.h>

#include <stdint.h>

#include <common/bk_err.h>
#include <components/log.h>

#include "driver/flash.h"
#include "driver/flash_types.h"
#include "driver/flash_partition.h"
#include "driver/efuse.h"
#include "driver/otp.h"
#include "driver/wdt.h"

/****************************************************************************
 * Pre-processor definitions
 ****************************************************************************/

#define FLASH_TAG "bk_flash"

#define FLASH_UNPORTED(_name)                                              \
  do                                                                      \
    {                                                                     \
      static bool _warned;                                                \
      if (!_warned)                                                       \
        {                                                                 \
          _warned = true;                                                 \
          BK_LOGE(FLASH_TAG,                                              \
                  "%s: no RF calibration store on BK7258 yet; "           \
                  "calibration data is NOT available\n", (_name));        \
        }                                                                 \
    }                                                                     \
  while (0)

/****************************************************************************
 * Private data
 ****************************************************************************/

/* Zero-length descriptor: non-NULL so the caller above does not fault, but
 * describing an empty region so nothing treats it as usable storage.
 */

static bk_logic_partition_t g_bk7258_rf_partition_unmapped =
{
  .partition_owner       = BK_FLASH_EMBEDDED,
  .partition_description = "unmapped (BK7258 RF partition not defined)",
  .partition_start_addr  = 0,
  .partition_length      = 0,
  .partition_options     = 0,
};

/****************************************************************************
 * Partition lookup
 ****************************************************************************/

bk_logic_partition_t *bk_flash_partition_get_info(bk_partition_t partition)
{
  (void)partition;
  return &g_bk7258_rf_partition_unmapped;
}

/****************************************************************************
 * Read paths -- the real gate. Each fails without writing the output buffer.
 ****************************************************************************/

bk_err_t bk_flash_read_bytes(uint32_t address, uint8_t *user_buf,
                             uint32_t size)
{
  (void)address;
  (void)user_buf;
  (void)size;
  FLASH_UNPORTED("bk_flash_read_bytes");
  return BK_FAIL;
}

bk_err_t bk_flash_partition_read(bk_partition_t partition, uint8_t *out_buffer,
                                 uint32_t offset, uint32_t buffer_len)
{
  (void)partition;
  (void)out_buffer;
  (void)offset;
  (void)buffer_len;
  FLASH_UNPORTED("bk_flash_partition_read");
  return BK_FAIL;
}

/****************************************************************************
 * Write paths -- refused, not stubbed
 *
 * These exist because the PHY can write calibration results back. Writing to a
 * guessed address could corrupt a real partition (the team layout has no RF
 * region), so refusal is the only correct answer here.
 ****************************************************************************/

bk_err_t bk_flash_write_bytes(uint32_t address, const uint8_t *user_buf,
                              uint32_t size)
{
  (void)address;
  (void)user_buf;
  (void)size;
  FLASH_UNPORTED("bk_flash_write_bytes");
  return BK_FAIL;

