/*
 * chips/bk7258/wifi/glue/flash_shim.c
 *
 * Flash / partition / eFuse / OTP accessors that the vendored bk_phy_adapter.c
 * registers into the PHY capability table, so libbk_phy.a reads RF calibration
 * through them.
 *
 * ==== Why these are stubs, and why they are shaped like this ====
 *
 * The RF calibration blob lives in a dedicated flash partition. Upstream's genie
 * project puts it at the tail of an 8 MiB flash (SYS_RF 0x007fe000, 0x1000 bytes,
 * per its generated partitions_gen.h). This team repo's own partition table
 * (board/bk7258-devkit/packaging/bundled/bk_ota_partitions.json) declares only
 * bootloader / app / app1 / download -- there is no RF partition yet. Flash
 * layout is a product decision, so this file does not invent one.
 *
 * The shape is forced by the caller:
 * bk_flash_partition_get_rf_firmware_info() (bk_phy_adapter.c:224-229) does
 *
 *     pt = bk_flash_partition_get_info(BK_PARTITION_SYS_RF);
 *     return pt->partition_start_addr;
 *
 * with no NULL check. So returning NULL is not "safe failure", it is a null
 * dereference during PHY init. Instead:
 *
 *   - get_info() returns a real, zero-length descriptor: no crash, and a length
 *     of 0 says "nothing here" to anything that bothers to look;
 *   - the actual gate is the read path. Every read fails without touching the
 *     output buffer, so no garbage can be mistaken for calibration data;
 *   - every write is refused outright, so nothing can be persisted to an
 *     address that only looks plausible.
 *
 * That ordering matters: silently returning zeros would let the PHY calibrate
 * against fabricated values, which is worse than a clean failure -- it can mean
 * out-of-spec RF output.
 *
 * Temperature/voltage monitoring lives in glue/analog_shim.c, not here.
 *
 * Before RF bring-up (plan step 4) this file must be implemented for real: add
 * the RF partition to the team flash layout, then read it via the NuttX
 * MTD/progmem interface. Tracked in ABI_AUDIT.md alongside the analog items.
 */

#include <nuttx/config.h>

#include <stdint.h>

#include <common/bk_err.h>
#include <components/log.h>

#include "driver/flash.h"
#include "driver/flash_types.h"
#include "driver/flash_partition.h"
#include "driver/efuse.h"
#include "driver/otp.h"
#include "driver/wdt.h"

/****************************************************************************
 * Pre-processor definitions
 ****************************************************************************/

#define FLASH_TAG "bk_flash"

#define FLASH_UNPORTED(_name)                                              \
  do                                                                      \
    {                                                                     \
      static bool _warned;                                                \
      if (!_warned)                                                       \
        {                                                                 \
          _warned = true;                                                 \
          BK_LOGE(FLASH_TAG,                                              \
                  "%s: no RF calibration store on BK7258 yet; "           \
                  "calibration data is NOT available\n", (_name));        \
        }                                                                 \
    }                                                                     \
  while (0)

/****************************************************************************
 * Private data
 ****************************************************************************/

/* Zero-length descriptor: non-NULL so the caller above does not fault, but
 * describing an empty region so nothing treats it as usable storage.
 */

static bk_logic_partition_t g_bk7258_rf_partition_unmapped =
{
  .partition_owner       = BK_FLASH_EMBEDDED,
  .partition_description = "unmapped (BK7258 RF partition not defined)",
  .partition_start_addr  = 0,
  .partition_length      = 0,
  .partition_options     = 0,
};

/****************************************************************************
 * Partition lookup
 ****************************************************************************/

bk_logic_partition_t *bk_flash_partition_get_info(bk_partition_t partition)
{
  (void)partition;
  return &g_bk7258_rf_partition_unmapped;
}

/****************************************************************************
 * Read paths -- the real gate. Each fails without writing the output buffer.
 ****************************************************************************/

bk_err_t bk_flash_read_bytes(uint32_t address, uint8_t *user_buf,
                             uint32_t size)
{
  (void)address;
  (void)user_buf;
  (void)size;
  FLASH_UNPORTED("bk_flash_read_bytes");
  return BK_FAIL;
}

bk_err_t bk_flash_partition_read(bk_partition_t partition, uint8_t *out_buffer,
