  (void)addr;
  (void)data;
  FLASH_UNPORTED("bk_efuse_read_byte");
  return BK_FAIL;
}

bk_err_t bk_efuse_write_byte(uint8_t addr, uint8_t data)
{
  /* Refused outright: eFuse programming is irreversible. */

