  (void)arg;
  return 0;
}

#ifdef CONFIG_BK7258_COMPONENT_AP
/* BK7258 AON GPIO configuration bits. GPIO output enable is active-low. */

#define BK7258_GPIO_OUTPUT_VALUE  (UINT32_C(1) << 1)
#define BK7258_GPIO_INPUT_ENABLE  (UINT32_C(1) << 2)
#define BK7258_GPIO_OUTPUT_DISABLE (UINT32_C(1) << 3)
#define BK7258_GPIO_PULL_MODE     (UINT32_C(1) << 4)
#define BK7258_GPIO_PULL_ENABLE   (UINT32_C(1) << 5)
#define BK7258_GPIO_SECOND_FUNC   (UINT32_C(1) << 6)

static inline uint32_t bk7258_ap_gpio_read(unsigned int pin)
{
  return *(volatile uint32_t *)BK7258_GPIO_CFG(pin);
}

static inline void bk7258_ap_gpio_write(unsigned int pin, uint32_t value)
{
  *(volatile uint32_t *)BK7258_GPIO_CFG(pin) = value;
  __asm__ volatile ("dsb" : : : "memory");
}

static void bk7258_ap_heartbeat_led_write(bool on)
{
  uint32_t config =
    bk7258_ap_gpio_read(BOARD_AP_HEARTBEAT_LED_PIN);
  bool high = BOARD_AP_HEARTBEAT_LED_ACTIVE_HIGH ? on : !on;

  if (high)
    {
      config |= BK7258_GPIO_OUTPUT_VALUE;
    }
  else
    {
      config &= ~BK7258_GPIO_OUTPUT_VALUE;
    }

  bk7258_ap_gpio_write(BOARD_AP_HEARTBEAT_LED_PIN, config);
}

static void bk7258_ap_heartbeat_led_initialize(void)
{
  uint32_t config =
    bk7258_ap_gpio_read(BOARD_AP_HEARTBEAT_LED_PIN);

  /* Select ordinary GPIO, disable input and pulls, enable output, and seed the
   * inactive level before the task starts toggling the pin. */

  config &= ~(BK7258_GPIO_OUTPUT_VALUE |
              BK7258_GPIO_INPUT_ENABLE |
              BK7258_GPIO_OUTPUT_DISABLE |
              BK7258_GPIO_PULL_MODE |
              BK7258_GPIO_PULL_ENABLE |
              BK7258_GPIO_SECOND_FUNC);
  bk7258_ap_gpio_write(BOARD_AP_HEARTBEAT_LED_PIN, config);
  bk7258_ap_heartbeat_led_write(false);
}

/****************************************************************************
 * chips/bk7258/bk7258_start.c
 ****************************************************************************/

#include <nuttx/config.h>

#include <stdint.h>

#include <nuttx/cache.h>
#include <nuttx/init.h>
#include <nuttx/irq.h>

#include "arm_internal.h"
#include "nvic.h"
#include "bk7258_internal.h"

extern const void *const _vectors[];

void __start(void)
{
  const uint32_t *src;
  uint32_t *dest;

  /* Keep all exceptions masked until the vector base and C runtime state are
   * coherent. This first CP L0 image intentionally has no RAM-vector or NS
   * handoff path. */

  /* BASEPRI alone leaves high-priority configurable IRQs unmasked. The
   * opaque Bootloader may have left routes enabled, so use PRIMASK until
   * up_irqinitialize installs the NuttX vector/handler state. */

  __asm__ volatile ("cpsid i" : : : "memory");

  /* The locked Bootloader/vendor tuple enables D-cache. NuttX replaces that
   * runtime and the RPMsg transport deliberately uses uncached shared SRAM,
   * so clean and disable any inherited D-cache before touching .data, .bss,
   * SWAP or RPMSG_SHM. */

  if ((getreg32(NVIC_CFGCON) & NVIC_CFGCON_DC) != 0)
    {
      up_disable_dcache();
    }

  /* Make instruction fetch deterministic rather than inheriting an opaque
   * Bootloader cache state. The BK7258 TIMER_ARCH time read must complete its
   * resource/status snapshot between two SysTick updates. */

  up_enable_icache();

  putreg32((uintptr_t)_vectors, NVIC_VECTAB);
  __asm__ volatile ("dsb\n\tisb" : : : "memory");

  for (dest = (uint32_t *)_sbss; dest < (uint32_t *)_ebss; )
    {
      *dest++ = 0;
    }

  for (src = (const uint32_t *)_eronly, dest = (uint32_t *)_sdata;
       dest < (uint32_t *)_edata; )
    {
      *dest++ = *src++;
    }

  bk7258_lowsetup();
  bk7258_lowputc('B');
  bk7258_lowputc('K');
  bk7258_lowputc('\r');
  bk7258_lowputc('\n');

#ifdef USE_EARLYSERIALINIT
  arm_earlyserialinit();
#endif

  nx_start();

  for (; ; )
    {
    }
}
