/*
 * chips/bk7258/wifi/bk7258_wifi_init.c
 *
 * BK7258 Wi-Fi initialization entry (NuttX side).
 *
 * Owns the single per-device instance and drives bring-up in two stages:
 *
 *   1. NuttX side: HW glue (clock/power/IRQ) -> board config -> netdev
 *      lower-half register. The NuttX scheduler is already running, so there is
 *      no OSAL-init step.
 *   2. Vendor side: the Armino runtime, in upstream's order (see bk_init.c,
 *      app_phy_init + app_wifi_init).
 *
 * ==== Why stage 2 exists at all right now ====
 *
 * It is what makes the link real. With no live call into the vendored glue,
 * --gc-sections discards the whole region as unreachable -- taking the rtos_
 * and pbuf_ shims with it -- and the prebuilts are never pulled in. That was
 * the state recorded in ABI_AUDIT.md section 7: "links successfully" while none
 * of the vendor symbols were in the image, and the 308-symbol glue contract
 * entirely unverified.
 *
 * ==== What this does NOT mean ====
 *
 * Reaching bk_wifi_init() is a link-closure check, not working Wi-Fi. Every
 * blocking item in ABI_AUDIT.md section 5 is still open: the chip revision id
 * reads 0, 19 analog register entry points do not touch hardware, there is no
 * RF calibration store, and the OTP ids belong to another flash layout. So the
 * PHY comes up uncalibrated. Do not read a successful boot here as RF bring-up
 * (plan step 4).
 */

#include <nuttx/config.h>

#include "bk7258_wifi_internal.h"

#ifdef CONFIG_BK7258_WIFI_VENDOR_RUNTIME
/* Vendored Armino runtime entry points, in the order upstream calls them. */

#include <common/bk_err.h>
#include <components/event.h>
#include <components/log.h>
#include <components/netif.h>
#include <modules/wifi.h>
#include <modules/wifi_types.h>

#include "bk_phy_adapter.h"
#include "bk_rf_adapter.h"
#endif

/****************************************************************************
 * Pre-processor definitions
 ****************************************************************************/

#define WIFI_TAG "bk_wifi_init"

/****************************************************************************
 * Private data
 ****************************************************************************/

static struct bk7258_wifi_s g_bk7258_wifi;

/****************************************************************************
 * Private functions
 ****************************************************************************/

#ifdef CONFIG_BK7258_WIFI_VENDOR_RUNTIME

/****************************************************************************
 * Name: bk7258_wifi_vendor_init
 *
 * Description:
 *   Bring up the vendored Armino Wi-Fi runtime, following upstream's sequence
 *   (bk_init.c: app_phy_init then app_wifi_init).
 *
 *   PHY/RF adapters first: they install the capability tables that
 *   libbk_phy.a reads, and bk_wifi_init() validates its own table before doing
 *   anything else.
 *
 *   Failures are logged and returned, never swallowed. A partial vendor init is
 *   worse than none: the netdev would be registered and appear usable while the
 *   MAC never actually started.
 *
 ****************************************************************************/

static int bk7258_wifi_vendor_init(void)
{
  wifi_init_config_t config = WIFI_DEFAULT_INIT_CONFIG();
  bk_err_t ret;

  /* PHY and RF adapters return void upstream -- there is no status to check. */

  bk_phy_adapter_init();
  bk_rf_adapter_init();

  ret = bk_event_init();
  if (ret != BK_OK)
    {
      BK_LOGE(WIFI_TAG, "bk_event_init failed: %d\n", (int)ret);
      return -ENODEV;
    }

  /* Bridges the vendor netif API onto NuttX netdev; see glue/netif_shim.c. */

  ret = bk_netif_init();
  if (ret != BK_OK)
    {
      BK_LOGE(WIFI_TAG, "bk_netif_init failed: %d\n", (int)ret);
      return -ENODEV;
    }

  /* config carries &g_wifi_os_funcs / &g_wifi_os_variable, the two tables the
   * prebuilt drives everything through. Note they live in .dtcm_sec_data, which
   * board/bk7258-devkit/scripts/flash.ld must collect into .data -- otherwise
   * they are never copied at startup and this call hands the prebuilt garbage
   * while still passing its non-NULL check.
   */

  ret = bk_wifi_init(&config);
  if (ret != BK_OK)
    {
      BK_LOGE(WIFI_TAG, "bk_wifi_init failed: %d\n", (int)ret);
      return -ENODEV;
    }

  BK_LOGI(WIFI_TAG,
          "vendor runtime initialized -- NOT calibrated, see ABI_AUDIT.md #5\n");
  return 0;
}
#endif /* CONFIG_BK7258_WIFI_VENDOR_RUNTIME */

/****************************************************************************
 * Public entry
 ****************************************************************************/

int bk7258_wifi_initialize(void)
{
  int ret;

  ret = bk7258_wifi_hw_init();
  if (ret < 0)
    {
      return ret;
    }

  ret = bk7258_wifi_board_init();
  if (ret < 0)
    {
      return ret;
    }

#ifdef CONFIG_BK7258_WIFI_VENDOR_RUNTIME
  /* Before registering the netdev: a registered interface that cannot carry
   * traffic is harder to diagnose than a missing one.
   */

  ret = bk7258_wifi_vendor_init();
  if (ret < 0)
    {
      return ret;
    }
#endif

  ret = bk7258_wifi_lower_init(&g_bk7258_wifi);
  if (ret < 0)
    {
      return ret;
    }

  return bk7258_wifi_lower_register(&g_bk7258_wifi);
}
