 */

#include <nuttx/config.h>

#ifdef CONFIG_BK7258_WIFI
#include "wifi/bk7258_wifi_internal.h"
#endif

void arm_netinitialize(void)
{
#ifdef CONFIG_BK7258_WIFI
  bk7258_wifi_initialize();
#endif
}

